    letters = " ".join(letter + "+" for letter in string)
    xoxo = "-".join(letters.split())
    return xoxo

@register.tag
def page_title(parser, token):
    r"""Set the title of the page.
    Usage::
        {% page_title %}Your title here{% endpage_title %}
    """
    nodelist = parser.parse(('endpage_title',))
    parser.delete_first_token()
    return JavaScriptAssignNode(nodelist, 'document.title')

@register.tag
def setvar(parser, token):
    """Get a variable value from context and set it for use
    in the current block. If variable cannot be found, set it
    to an empty string.

    Example usage::

        {% setvar foo = bar.baz %}

    If bar.baz cannot be found, foo will be an empty string.
    If bar.baz is False, foo will be False. If bar.baz is
    boolean True, foo will be the string "True".
    """
    bits = token.split_contents()
    assert len(bits) >= 3
    assert bits[-2] == '='
    source = parser.compile_filter(" ".join(bits[2:]))
    return SetVarNode(source, bits[1])
setvar.built_in = True

class SetVarNode(template.Node):
    def __init__(self, source, var_name):
        self.source = source
        self.var_name = var_name

    def render(self, context):
        output = self.source.render(context)
        if self.var_name in context:
            old_value = context[self.var_name]
            context[self.var_name] = output
            try:
                result = self.nodelist.render(context)
            finally:
                context[self.var_name] = old_value
            return result
        else:
            context[self.var_name] = output
            return self.nodelist.render(context)

