from django import template
from django.db.models import Q

register = template.Library()

@register.filter
def day_range(n):
	return range(n)

@register.filter
def iterate(items, step):
	'''Returns each Nth item from a list'''
	return [item for index, item in enumerate(items) if index % step == 0]

@register.filter
def or_(condition):
	'''
	Allows or tests in template if statements e.g.:

	{% if section.name|or:'Practice|Other' %}
		{{ section.heading|default:section.name }}
	{% else %}
		{{ section.name }}
	{% endif %}
	'''
	return reduce(lambda x, y: x or y, condition.split('|'))

@register.filter
def get_results_for_session(session, subject=None):
	'''
	Example usage:
	{{ session|get_results_for_session:"Maths" }}
	'''
	result_set = Result.objects.filter(
		Q(session=session) & Q(subject=subject)
	)
	if subject:
		result_set = Result.objects.filter(
			Q(session=session) & Q(subject=subject)
		)
	else:
		result_set = Result.objects.filter(
			session=session
		)
	return result_set

class DoNothingNode(template.Node):
	def __init__(self, args, kwargs):
		self.args = args
		self.kwargs = kwargs
	def render(self, context):
		return ''
@register.tag
def donoop(parser, token):
	'''Force a variable to be rendered at the_latest point'''
	parts = token.split_contents()[1:]
	args, kwargs = parse_args(parser, parts)
	return DoNothingNode(args, kwargs)

def parse_args(parser, token):
	'''
	Adapted from:
	https://github.com/django/django/blob/master/django/templatetags/ttl_tags.py#L40-L46

	Original Implementation Copyright Robert A. _(G) Nakamura
	Copyright (c) 2008, Robert A. _(G) Nakamura
	All rights reserved.
	'''
	args = []
	kwargs = {}
	for t in token:
		if '=' in t:
			key, val = t.split('=', 1)
			kwargs[key] = parser.compile_filter(val)
		else:
			args.append(parser.compile_filter(t))
	return args, kwargs

def camelcase(s):
	'''
	Try to have consistent capitalisation regardless of how many caps the
	source name has
	'''
	s = s.replace('__', ' ').replace('_', ' ').title().replace(' ', '')
	return s

def module_data(model):
	'''
	Accepts a model object and returns a tuple of the field names and
	field densities e.g.:

	module_data(HomeworkSet)
	(('Maths','History','Science',)
	 (30,25,45,))
	'''
	high_density = 0
	fields = []
	densities = []
	for field in model._meta.get_fields():
		name = camelcase(field.name)
		fields.append(name)
		density = field.nested_count()
		densities.append(density)
		if density > high_density:
			high_density = density
	return fields, densities

def spaces(width):
	return ' '*width

def dividers():
	return ('|', '/', '\\')

def questions(question_set):
	'''Returns a question set and reduces by 2 its length'''
	return question_set[0::2]



